function removeteam(n){const t=Swal.mixin({customClass:{confirmButton:"btn btn-success",cancelButton:"btn btn-danger"},buttonsStyling:!1});t.fire({title:"Are you sure?",text:"You won't be able to revert this!",icon:"warning",showCancelButton:!0,confirmButtonText:"Yes, delete it!",cancelButtonText:"No, cancel!",reverseButtons:!0}).then(i=>{i.isConfirmed?$.ajax({type:"DELETE",url:"https://localhost:44348"+n,success:function(n){$.unblockUI();n.success?(swal.fire("Deleted!",n.message,"success"),datatablez.ajax.reload()):swal.fire("Deleted!",n.message,"error")},beforeSend:function(){blockcallback()},error:function(){$.unblockUI();Swal.fire({icon:"error",title:"Oops...",text:"Something went wrong!",footer:"Check internet connectivity"})},complete:function(){$.unblockUI()}}):i.dismiss===Swal.DismissReason.cancel&&t.fire("Cancelled","Team Member Record NOT Deleted","error")})}function blockcallback(){$.blockUI({message:'<div class="bs-spinner mt-4 mt-lg-0"><div class= "spinner-border text-success mr-2 mt-2" style="width: 10rem; height: 10rem;" role="status"><span class="sr-only">Loading...<\/span><\/div> ',fadeIn:800,overlayCSS:{backgroundColor:"#1b2024",opacity:.8,zIndex:1200,cursor:"wait"},css:{border:0,color:"#fff",zIndex:1201,padding:0,backgroundColor:"transparent"},onBlock:function(){}})}var font,clazz,datatablez;$(document).ready(function(){datatablez=$("#teammanager").DataTable({processing:!0,serverSide:!0,filter:!0,paging:!0,responsive:!0,ajax:{url:"/Home/TeamManagers",type:"POST",datatype:"json"},columnDefs:[{targets:[0],visible:!0,searchable:!0}],columns:[{data:"id",render:function(n,t,i,r){return r.row+r.settings._iDisplayStart+1}},{data:"fullname",autoWidth:!0},{data:"position",autoWidth:!0},{data:"email",autoWidth:!0},{data:"phone",autoWidth:!0},{data:"hierarchy",autoWidth:!0},{data:"createdDate",render:function(n){if(!n)return"Null";var t=new Date(n),i=t.toISOString().slice(0,19).replace("T"," "),r=t.getHours(),u=r>=12?"pm":"am";return i+" "+u}},{data:null,render:function(n){return`
                        <div class="d-flex justify-content-between">
                            <a class="btn btn-primary btn-sm" title="Edit Team data" href="/WebsiteManager/TeamManagers/Upsert?id=${n.id}" style="cursor:pointer">
                                <i class="fa fa-edit"></i>
                            </a>
                            &nbsp;
                            <a onclick=removeteam("/api/RemoveTeamManagement/${n.id}") title="Permanently Remove team member" class="btn btn-danger btn-sm" href="#" style="cursor:pointer">
                                <i class="fa fa-trash"></i>
                            </a>
                        </div>
                    `}}]})});